#!/usr/bin/env python3
"""Recompute NLI combo with alphabetical tiebreaking for Mistral PW600 + FOLIO."""
import json
from collections import Counter
from scipy.stats import binomtest

VALID = {"True", "False", "Unknown"}
WEIGHTS_PW = [1, 3, 5]
WEIGHTS_FOLIO = [1, 3]

def majority_alpha(vote_dist):
    filtered = {k: v for k, v in vote_dist.items() if k in VALID}
    if not filtered:
        return "Unknown"
    max_count = max(filtered.values())
    winners = sorted([k for k, v in filtered.items() if v == max_count])
    return winners[0]

def combo_alpha(vote_dist, nli_pred, w):
    combined = {}
    for k, v in vote_dist.items():
        if k in VALID:
            combined[k] = combined.get(k, 0) + v
    if nli_pred in VALID:
        combined[nli_pred] = combined.get(nli_pred, 0) + w
    if not combined:
        return "Unknown"
    max_count = max(combined.values())
    winners = sorted([k for k, v in combined.items() if v == max_count])
    return winners[0]

def mcnemar_exact(b, c):
    n = b + c
    if n == 0:
        return 1.0
    return binomtest(min(b, c), n, 0.5).pvalue

def process_generator(name, questions, weights):
    n = len(questions)
    sc_correct = 0
    sc_results = []
    for q in questions:
        sc_ans = majority_alpha(q["sc_vote_distribution"])
        correct = (sc_ans == q["gold"])
        sc_results.append(correct)
        if correct:
            sc_correct += 1
    sc_acc = sc_correct / n

    combo_data = {}
    for w in weights:
        combo_correct_list = []
        b_count = 0
        c_count = 0
        for i, q in enumerate(questions):
            combo_ans = combo_alpha(q["sc_vote_distribution"], q["deberta_pred"], w)
            combo_ok = (combo_ans == q["gold"])
            combo_correct_list.append(combo_ok)
            sc_ok = sc_results[i]
            if combo_ok and not sc_ok:
                b_count += 1
            if not combo_ok and sc_ok:
                c_count += 1

        combo_n_correct = sum(combo_correct_list)
        combo_acc = combo_n_correct / n
        delta_pp = round((combo_acc - sc_acc) * 100, 2)
        p_val = mcnemar_exact(b_count, c_count)

        combo_data[f"w{w}"] = {
            "acc": round(combo_acc * 100, 2),
            "n_correct": combo_n_correct,
            "delta_pp": delta_pp,
            "mcnemar_p": p_val,
            "b": b_count,
            "c": c_count
        }

    return {
        "sc": {"acc": round(sc_acc * 100, 2), "n_correct": sc_correct},
        **combo_data
    }

# === Mistral-7B PW600 ===
print("Loading Mistral-7B PW600...")
with open("/root/symb_invariant_consensus/results/exp046_mistral_7b_pw600/exp046_results.json") as f:
    mistral_sc = json.load(f)
with open("/root/symb_invariant_consensus/results/direction_r_nli_pw600/results.json") as f:
    mistral_nli = json.load(f)

mistral_sc_by_pid = {}
for r in mistral_sc["results"]:
    mistral_sc_by_pid[r["problem_id"]] = {
        "sc_vote_distribution": r["sc_vote_distribution"],
        "gold": r["ground_truth"]
    }

nli_pq = mistral_nli["per_question"]
mistral_questions = []
for pid in mistral_sc_by_pid:
    if pid not in nli_pq:
        continue
    mistral_questions.append({
        "pid": pid,
        "gold": mistral_sc_by_pid[pid]["gold"],
        "sc_vote_distribution": mistral_sc_by_pid[pid]["sc_vote_distribution"],
        "deberta_pred": nli_pq[pid]["deberta_pred"]
    })
print(f"  Merged: {len(mistral_questions)} questions")
mistral_result = process_generator("Mistral-7B", mistral_questions, WEIGHTS_PW)
print(f"  Mistral SC: {mistral_result['sc']}")
for w in WEIGHTS_PW:
    print(f"  Mistral w{w}: {mistral_result[f'w{w}']}")

# === Mistral-7B FOLIO ===
print("\nLoading Mistral-7B FOLIO...")
with open("/root/symb_invariant_consensus/results/exp033_mistral_7b_folio204/sc_answer_matrix.json") as f:
    folio_sc_matrix = json.load(f)
with open("/root/symb_invariant_consensus/results/direction_r_nli_large/results.json") as f:
    folio_nli = json.load(f)

folio_nli_pq = folio_nli["per_question"]
folio_questions = []
for fid in sorted(folio_sc_matrix.keys(), key=lambda x: int(x.split("_")[1])):
    raw_answers = folio_sc_matrix[fid]["answers"]
    gold = folio_sc_matrix[fid]["ground_truth"]
    # Compute vote distribution from raw answers
    vote_dist = {}
    for a in raw_answers:
        if a in VALID:
            vote_dist[a] = vote_dist.get(a, 0) + 1

    if fid not in folio_nli_pq:
        continue
    folio_questions.append({
        "pid": fid,
        "gold": gold,
        "sc_vote_distribution": vote_dist,
        "deberta_pred": folio_nli_pq[fid]["deberta_pred"]
    })
print(f"  Merged: {len(folio_questions)} questions")
folio_result = process_generator("Mistral-7B-FOLIO", folio_questions, WEIGHTS_FOLIO)
print(f"  FOLIO SC: {folio_result['sc']}")
for w in WEIGHTS_FOLIO:
    print(f"  FOLIO w{w}: {folio_result[f'w{w}']}")

# Save
output = {
    "Mistral-7B-PW600": mistral_result,
    "Mistral-7B-FOLIO": folio_result
}
with open("/root/symb_invariant_consensus/results/alpha_recompute_25068.json", "w") as f:
    json.dump(output, f, indent=2)
print(f"\nSaved to /root/symb_invariant_consensus/results/alpha_recompute_25068.json")
